<?php
require __DIR__.'/src/commerce.php';
$error='';$mode=$_GET['mode']??'login';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$email=mb_strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
if($action==='logout'){unset($_SESSION['customer_id']);session_regenerate_id(true);redirect('account.php');}
if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190){$error='البريد الإلكتروني غير صحيح.';}
elseif($action==='register'){$name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>120||strlen($password)<12){$error='أدخل الاسم وكلمة مرور لا تقل عن 12 حرفًا.';}else{try{$q=db()->prepare('INSERT INTO customers(name,email,password_hash) VALUES(?,?,?)');$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$_SESSION['customer_id']=(int)db()->lastInsertId();session_regenerate_id(true);redirect('orders.php');}catch(PDOException $e){$error='تعذر التسجيل؛ قد يكون البريد مستخدمًا.';}}}
elseif($action==='login'){$q=db()->prepare('SELECT id,password_hash FROM customers WHERE email=?');$q->execute([$email]);$u=$q->fetch();if($u&&password_verify($password,$u['password_hash'])){$_SESSION['customer_id']=(int)$u['id'];session_regenerate_id(true);redirect('orders.php');}$error='بيانات الدخول غير صحيحة.';}}
$u=customer();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css?v=4"><title>حسابي | نَسَق</title></head><body><header class="site-header"><nav class="wrap site-nav"><a class="brand" href="index.php"><span class="brand-mark">ن</span>نَسَق</a><a class="btn secondary" href="index.php">الرئيسية</a></nav></header><main class="wrap"><section class="pagehead"><h1>حساب العميل</h1><p>تابع طلباتك من مكان واحد.</p></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($u):?><div class="panel"><h2>مرحبًا، <?=e($u['name'])?></h2><p><?=e($u['email'])?></p><a class="btn" href="orders.php">طلباتي</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="btn secondary" type="submit">تسجيل الخروج</button></form></div><?php else:?><div class="panel account-box"><div class="admin-actions"><a class="btn secondary" href="account.php?mode=login">دخول</a><a class="btn secondary" href="account.php?mode=register">إنشاء حساب</a></div><form method="post" class="settings-form"><?=csrf_field()?><input type="hidden" name="action" value="<?=$mode==='register'?'register':'login'?>"><?php if($mode==='register'):?><label>الاسم<input name="name" required maxlength="120" autocomplete="name"></label><?php endif;?><label>البريد الإلكتروني<input type="email" name="email" required autocomplete="email"></label><label>كلمة المرور<input type="password" name="password" required autocomplete="<?=$mode==='register'?'new-password':'current-password'?>" <?=$mode==='register'?'minlength="12"':''?>></label><button class="btn" type="submit"><?=$mode==='register'?'إنشاء الحساب':'تسجيل الدخول'?></button></form></div><?php endif;?></main></body></html>